n  /// Commission percent frozen when the invoice was issued (null = use the deal's current one).\n  commissionPct      Decimal?      @db.Decimal(5, 2)\n  paymentTerms       String?\n  notes              String?\n  /// Frozen copy of seller/buyer legal data and terms at the moment of creation.\n  snapshot           Json\n  correctsInvoiceId  String?\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  dealTermsVersion DealTermsVersion      @relation(fields: [dealTermsVersionId], references: [id], onDelete: Restrict)\n  sellerCompany    Company?              @relation(\"InvoiceSellerCompany\", fields: [sellerCompanyId], references: [id], onDelete: Restrict)\n  buyerCompany     Company?              @relation(\"InvoiceBuyerCompany\", fields: [buyerCompanyId], references: [id], onDelete: Restrict)\n  correctsInvoice  Invoice?              @relation(\"InvoiceCorrections\", fields: [correctsInvoiceId], references: [id], onDelete: Restrict)\n  corrections      Invoice[]             @relation(\"InvoiceCorrections\")\n  items            InvoiceItem[]\n  payments         PaymentRecord[]\n  statusHistory    InvoiceStatusChange[]\n  commission       Commission?\n\n  @@index([sellerCompanyId, status])\n  @@index([buyerCompanyId, status])\n  @@index([sellerUserId])\n  @@index([buyerUserId])\n  @@index([dueDate])\n}\n\nmodel InvoiceItem {\n  id          String  @id @default(cuid())\n  invoiceId   String\n  name        String\n  description String?\n  quantity    Decimal @db.Decimal(18, 3)\n  unit        String\n  unitPrice   Decimal @db.Decimal(18, 2)\n  lineTotal   Decimal @db.Decimal(18, 2)\n  sortOrder   Int     @default(0)\n\n  invoice Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId])\n}\n\nmodel InvoiceStatusChange {\n  id          String         @id @default(cuid())\n  invoiceId   String\n  fromStatus  InvoiceStatus?\n  toStatus    InvoiceStatus\n  changedById String\n  co